
    "use strict";

    /* ========== 通用导航与反馈 ========== */
    const $ = (selector, root = document) => root.querySelector(selector);
    const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
    let currentScreen = "connection";
    let toastTimer;

    function showToast(message) {
      const toast = $("#toast");
      toast.textContent = message;
      toast.classList.add("show");
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => toast.classList.remove("show"), 2100);
    }

    function navigate(name) {
      $$(".screen").forEach(screen => screen.classList.toggle("active", screen.id === `screen-${name}`));
      currentScreen = name;
      $("#parameter-sheet").classList.remove("visible");
      if (name === "gallery") renderGallery();
      if (name === "queue") renderQueue();
      if (name === "recipes") renderRecipe();
      if (name === "portfolio") renderPortfolio();
    }

    document.addEventListener("click", event => {
      const route = event.target.closest("[data-go]");
      if (route) navigate(route.dataset.go);
    });

    function fitDevice() {
      const scale = Math.min(1, (window.innerWidth - 16) / 375, (window.innerHeight - 16) / 812);
      const stage = $("#prototype-stage");
      stage.style.width = `${375 * scale}px`;
      stage.style.height = `${812 * scale}px`;
      $("#device").style.transform = `scale(${scale})`;
    }
    window.addEventListener("resize", fitDevice);
    fitDevice();

    /* ========== 界面 1：PTP 握手 ========== */
    let connectionRun = 0;
    let connectedCamera = "";

    function beginConnection(camera) {
      const run = ++connectionRun;
      const overlay = $("#handshake-overlay");
      overlay.classList.remove("connected");
      overlay.classList.add("visible");
      $("#handshake-title").textContent = `正在连接 ${camera}`;
      $("#handshake-sub").textContent = "正在建立通道，请保持相机唤醒";
      const steps = $$(".handshake-step");
      steps.forEach(step => {
        step.classList.remove("complete");
        $(".step-fill", step).style.width = "0";
        $(".step-copy span:last-child", step).textContent = "等待";
      });
      steps.forEach((step, index) => {
        setTimeout(() => {
          if (run !== connectionRun) return;
          $(".step-copy span:last-child", step).textContent = "进行中";
          $(".step-fill", step).style.width = "100%";
        }, index * 720);
        setTimeout(() => {
          if (run !== connectionRun) return;
          step.classList.add("complete");
          $(".step-copy span:last-child", step).textContent = "完成";
          if (index === 2) {
            overlay.classList.add("connected");
            connectedCamera = camera;
            $("#handshake-sub").textContent = `已连接 ${camera} · 会话就绪`;
            const state = $("#connection-state");
            state.classList.add("connected");
            $("#connection-state-text").textContent = `已连接 ${camera}`;
            setTimeout(() => {
              if (run !== connectionRun) return;
              overlay.classList.remove("visible");
              navigate("console");
              showToast(`${camera} 已就绪`);
            }, 650);
          }
        }, index * 720 + 560);
      });
    }

    $$("[data-camera]").forEach(button => button.addEventListener("click", () => beginConnection(button.dataset.camera)));
    $("#scan-camera").addEventListener("click", () => {
      showToast("发现 Z 6III · 信号强度良好");
      beginConnection("Z 6III");
    });
    $("#cancel-connect").addEventListener("click", () => {
      connectionRun++;
      $("#handshake-overlay").classList.remove("visible");
      showToast("已取消连接");
    });

    /* ========== 界面 2：取景工具、参数拨盘与快门 ========== */
    const toolState = { peak: false, zebra: false, grid: false, histogram: false };
    $$("[data-tool]").forEach(button => button.addEventListener("click", () => {
      const tool = button.dataset.tool;
      toolState[tool] = !toolState[tool];
      button.classList.toggle("active", toolState[tool]);
      button.setAttribute("aria-pressed", String(toolState[tool]));
      if (tool === "peak") $("#live-photo").classList.toggle("peaking", toolState[tool]);
      if (tool === "zebra") $("#zebra-overlay").classList.toggle("visible", toolState[tool]);
      if (tool === "grid") $("#grid-overlay").classList.toggle("visible", toolState[tool]);
      if (tool === "histogram") $("#histogram").classList.toggle("visible", toolState[tool]);
    }));

    const parameters = {
      mode: { title: "拍摄模式", value: "M", values: ["M", "A", "S", "P", "AUTO"] },
      shutter: { title: "快门速度", value: "1/250", values: ["1/60", "1/125", "1/250", "1/500", "1/1000", "1/2000"] },
      aperture: { title: "光圈", value: "f/2.8", values: ["f/1.4", "f/2", "f/2.8", "f/4", "f/5.6", "f/8", "f/11"] },
      iso: { title: "感光度", value: "ISO 400", values: ["ISO 100", "ISO 200", "ISO 400", "ISO 800", "ISO 1600", "ISO 3200", "ISO 6400"] },
      focal: { title: "焦距", value: "35mm", values: ["14mm", "24mm", "35mm", "50mm", "70mm", "85mm", "135mm", "200mm"] },
      wb: { title: "白平衡", value: "WB 5600K", values: ["WB 3200K", "WB 4300K", "WB 5600K", "WB 6500K", "WB 7500K"] }
    };
    let activeParameter = "shutter";
    let dialMoved = false;

    function renderParameters() {
      $$("[data-param]").forEach(button => button.textContent = parameters[button.dataset.param].value);
    }

    function centerDialOption(button) {
      const track = $("#dial-track");
      track.scrollTo({ left: button.offsetLeft - (track.clientWidth - button.clientWidth) / 2, behavior: "auto" });
    }

    function setParameterValue(value, center = false) {
      parameters[activeParameter].value = value;
      renderParameters();
      $$(".dial-option").forEach(option => {
        const selected = option.dataset.value === value;
        option.classList.toggle("selected", selected);
        if (selected && center) centerDialOption(option);
      });
    }

    function openDial(key) {
      activeParameter = key;
      $("#dial-title").textContent = parameters[key].title;
      const track = $("#dial-track");
      track.innerHTML = parameters[key].values.map(value => `<button class="dial-option ${value === parameters[key].value ? "selected" : ""}" data-value="${value}">${value}</button>`).join("");
      $("#parameter-sheet").classList.add("visible");
      requestAnimationFrame(() => {
        const selected = $(".dial-option.selected", track);
        if (selected) centerDialOption(selected);
      });
    }

    $$("[data-param]").forEach(button => button.addEventListener("click", () => openDial(button.dataset.param)));
    $("#close-dial").addEventListener("click", () => $("#parameter-sheet").classList.remove("visible"));
    $("#dial-track").addEventListener("click", event => {
      const option = event.target.closest(".dial-option");
      if (!option || dialMoved) return;
      setParameterValue(option.dataset.value, true);
    });

    const dialTrack = $("#dial-track");
    let dialStartX = 0;
    let dialStartScroll = 0;
    let dialDragging = false;
    dialTrack.addEventListener("pointerdown", event => {
      dialDragging = true;
      dialMoved = false;
      dialStartX = event.clientX;
      dialStartScroll = dialTrack.scrollLeft;
      dialTrack.setPointerCapture(event.pointerId);
      dialTrack.classList.add("dragging");
    });
    dialTrack.addEventListener("pointermove", event => {
      if (!dialDragging) return;
      const distance = event.clientX - dialStartX;
      if (Math.abs(distance) > 5) dialMoved = true;
      dialTrack.scrollLeft = dialStartScroll - distance;
    });
    function finishDial(event) {
      if (!dialDragging) return;
      dialDragging = false;
      dialTrack.classList.remove("dragging");
      if (dialTrack.hasPointerCapture(event.pointerId)) dialTrack.releasePointerCapture(event.pointerId);
      const center = dialTrack.scrollLeft + dialTrack.clientWidth / 2;
      const nearest = $$(".dial-option", dialTrack).reduce((best, option) => {
        const distance = Math.abs(option.offsetLeft + option.clientWidth / 2 - center);
        return !best || distance < best.distance ? { option, distance } : best;
      }, null);
      if (nearest) setParameterValue(nearest.option.dataset.value, true);
      setTimeout(() => { dialMoved = false; }, 0);
    }
    dialTrack.addEventListener("pointerup", finishDial);
    dialTrack.addEventListener("pointercancel", finishDial);

    let shotNumber = 843;
    let captureMode = "拍照";
    $$("[data-capture-mode]").forEach(button => button.addEventListener("click", () => {
      captureMode = button.dataset.captureMode;
      $$("[data-capture-mode]").forEach(item => item.classList.toggle("active", item === button));
      $("#shutter").classList.toggle("video", captureMode === "录像");
      showToast(`已切换至${captureMode}`);
    }));
    $("#shutter").addEventListener("click", () => {
      const shutter = $("#shutter");
      const flash = $("#shutter-flash");
      shutter.classList.add("pressed");
      flash.classList.remove("firing");
      void flash.offsetWidth;
      flash.classList.add("firing");
      setTimeout(() => { shutter.classList.remove("pressed"); flash.classList.remove("firing"); }, 190);
      shotNumber++;
      showToast(captureMode === "录像" ? "已开始录制 · 00:00:01" : captureMode === "B 门" ? "B 门曝光已开始" : `已拍摄 DSC_${String(shotNumber).padStart(4, "0")}.NEF`);
    });

    /* ========== 界面 3：图库、多选与照片预览 ========== */
    const photoFilters = ["saturate(.8) contrast(1.05)", "sepia(.2) saturate(.8)", "grayscale(.8) contrast(1.15)", "saturate(.65) brightness(.8)", "hue-rotate(-12deg) saturate(.7)", "contrast(1.18) brightness(.9)"];
    const cameraPhotos = Array.from({ length: 12 }, (_, index) => ({
      id: `camera-${index}`,
      name: `DSC_${String(837 + index).padStart(4, "0")}.${index % 4 === 3 ? "JPG" : index === 10 ? "MOV" : "NEF"}`,
      type: index === 10 ? "VIDEO" : index % 4 === 3 ? "JPEG" : "RAW",
      size: index === 10 ? 428.6 : index % 4 === 3 ? 14.8 : 48.2 + index * .7,
      filter: photoFilters[index % photoFilters.length],
      position: `${38 + (index % 4) * 8}% center`
    }));
    const phonePhotos = Array.from({ length: 12 }, (_, index) => ({
      id: `phone-${index}`,
      name: `NKC_${String(1120 + index)}.${index === 8 ? "MOV" : "JPG"}`,
      type: index === 8 ? "VIDEO" : index % 5 === 0 ? "RAW" : "JPEG",
      size: index === 8 ? 182.4 : index % 5 === 0 ? 45.6 : 9.8 + index * .4,
      filter: photoFilters[(index + 2) % photoFilters.length],
      position: `${34 + (index % 5) * 7}% center`
    }));
    let gallerySource = "camera";
    let galleryFilter = "all";
    let selectionMode = false;
    const selectedPhotos = new Set();
    let longPressTimer;
    let longPressAt = 0;
    let viewerPhotoId = "";

    function currentPhotos() { return gallerySource === "camera" ? cameraPhotos : phonePhotos; }
    function filteredPhotos() {
      if (galleryFilter === "all") return currentPhotos();
      if (galleryFilter === "selected") return currentPhotos().filter(photo => selectedPhotos.has(photo.id));
      return currentPhotos().filter(photo => photo.type === galleryFilter);
    }

    function renderGallery() {
      const photos = filteredPhotos();
      const grid = $("#photo-grid");
      grid.classList.toggle("selection-mode", selectionMode);
      grid.innerHTML = photos.map(photo => `<button class="photo-cell ${selectedPhotos.has(photo.id) ? "selected" : ""}" data-photo-id="${photo.id}" aria-label="${photo.name}"><img src="data:image/jpeg;base64," alt="" style="filter:${photo.filter};object-position:${photo.position}"><span class="selection-check"><svg class="icon"><use href="#i-check"/></svg></span>${photo.type === "RAW" ? '<span class="raw-badge">RAW</span>' : ""}${photo.type === "VIDEO" ? '<span class="video-badge"><svg class="icon"><use href="#i-play"/></svg>00:18</span>' : ""}</button>`).join("");
      $("#gallery-empty").hidden = photos.length > 0;
      $("#selection-bar").classList.toggle("visible", selectionMode);
      $(".queue-fab").style.display = selectionMode ? "none" : "grid";
      $("#download-selected span").textContent = `下载 ${selectedPhotos.size} 项`;
      $("#download-selected").disabled = selectedPhotos.size === 0;
      bindPhotoGestures();
      updateQueueCount();
    }

    function togglePhotoSelection(id) {
      if (selectedPhotos.has(id)) selectedPhotos.delete(id); else selectedPhotos.add(id);
      if (!selectionMode) selectionMode = true;
      renderGallery();
    }

    function openPhotoViewer(photo) {
      viewerPhotoId = photo.id;
      $("#viewer-name").textContent = photo.name;
      $("#viewer-info").textContent = `${photo.type === "VIDEO" ? "3840 × 2160 · 00:18" : "6048 × 4024"} · ISO 400 · f/2.8 · 1/250`;
      const image = $("#viewer-photo");
      image.style.filter = photo.filter;
      image.style.objectPosition = photo.position;
      $("#viewer-select").textContent = selectedPhotos.has(photo.id) ? "取消选择此照片" : "选择此照片";
      $("#photo-viewer").classList.add("visible");
    }

    function bindPhotoGestures() {
      $$(".photo-cell", $("#photo-grid")).forEach(cell => {
        cell.addEventListener("pointerdown", event => {
          if (event.button !== 0) return;
          clearTimeout(longPressTimer);
          longPressTimer = setTimeout(() => {
            longPressAt = Date.now();
            selectionMode = true;
            togglePhotoSelection(cell.dataset.photoId);
            if (navigator.vibrate) navigator.vibrate(12);
          }, 480);
        });
        ["pointerup", "pointercancel", "pointerleave"].forEach(type => cell.addEventListener(type, () => clearTimeout(longPressTimer)));
        cell.addEventListener("click", () => {
          if (Date.now() - longPressAt < 650) return;
          const photo = currentPhotos().find(item => item.id === cell.dataset.photoId);
          if (selectionMode || galleryFilter === "selected") togglePhotoSelection(photo.id); else openPhotoViewer(photo);
        });
        cell.addEventListener("contextmenu", event => event.preventDefault());
      });
    }

    $$("[data-source]").forEach(button => button.addEventListener("click", () => {
      gallerySource = button.dataset.source;
      $$("[data-source]").forEach(item => item.classList.toggle("active", item === button));
      galleryFilter = "all";
      selectionMode = false;
      $$("[data-filter]").forEach(item => item.classList.toggle("active", item.dataset.filter === "all"));
      renderGallery();
    }));
    $$("[data-filter]").forEach(button => button.addEventListener("click", () => {
      galleryFilter = button.dataset.filter;
      if (galleryFilter === "selected") selectionMode = true;
      $$("[data-filter]").forEach(item => item.classList.toggle("active", item === button));
      renderGallery();
    }));
    $("#select-all").addEventListener("click", () => {
      filteredPhotos().forEach(photo => selectedPhotos.add(photo.id));
      renderGallery();
    });
    $("#cancel-selection").addEventListener("click", () => {
      selectionMode = false;
      selectedPhotos.clear();
      galleryFilter = "all";
      $$("[data-filter]").forEach(item => item.classList.toggle("active", item.dataset.filter === "all"));
      renderGallery();
    });
    $("#close-viewer").addEventListener("click", () => $("#photo-viewer").classList.remove("visible"));
    $("#viewer-select").addEventListener("click", () => {
      togglePhotoSelection(viewerPhotoId);
      $("#photo-viewer").classList.remove("visible");
    });

    /* ========== 界面 4：真实走动的后台传输队列 ========== */
    let tasks = [
      { id: 1, name: "DSC_0837.NEF", size: 54.2, progress: 36, status: "active", speed: 2.9 },
      { id: 2, name: "DSC_0838.NEF", size: 51.8, progress: 68, status: "active", speed: 2.8 },
      { id: 3, name: "DSC_0842.MOV", size: 824.0, progress: 14, status: "active", speed: 2.7 },
      { id: 4, name: "DSC_0843.NEF", size: 49.6, progress: 0, status: "waiting", speed: 0 },
      { id: 5, name: "DSC_0829.JPG", size: 16.4, progress: 100, status: "done", speed: 0 },
      { id: 6, name: "DSC_0831.NEF", size: 244.0, progress: 42, status: "failed", speed: 0 }
    ];
    let queuePaused = false;
    let queueTouched = false;
    let nextTaskId = 7;

    function updateQueueCount() {
      const count = tasks.filter(task => task.status === "active" || task.status === "waiting").length;
      $("#queue-count").textContent = count;
      $("#queue-count").style.display = count ? "grid" : "none";
    }

    function taskStatus(task) {
      if (task.status === "active" && queuePaused) return "已暂停";
      return { active: "传输中", waiting: "等待中", done: "已完成", failed: "失败" }[task.status];
    }

    function formatSize(size) { return size >= 1000 ? `${(size / 1024).toFixed(1)} GB` : `${size.toFixed(1)} MB`; }
    function formatETA(seconds) {
      if (!Number.isFinite(seconds) || seconds <= 0) return "—";
      const minutes = Math.floor(seconds / 60);
      const remain = Math.round(seconds % 60);
      return minutes ? `${minutes} 分 ${String(remain).padStart(2, "0")} 秒` : `${remain} 秒`;
    }

    function renderQueue() {
      const active = tasks.filter(task => task.status === "active");
      const pending = tasks.filter(task => task.status === "active" || task.status === "waiting");
      const total = tasks.reduce((sum, task) => sum + task.size, 0);
      const remaining = pending.reduce((sum, task) => sum + task.size * (1 - task.progress / 100), 0);
      const speed = queuePaused ? 0 : active.reduce((sum, task) => sum + task.speed, 0);
      $("#queue-headline").textContent = pending.length ? `${pending.length} 个进行中` : tasks.length ? "没有进行中的任务" : "队列已清空";
      if (queueTouched) {
        $("#queue-total").textContent = formatSize(total);
        $("#queue-eta").textContent = formatETA(remaining / (speed || 1));
        $("#queue-speed").textContent = `${speed.toFixed(1)} MB/s`;
      }
      $("#queue-list").innerHTML = tasks.length ? tasks.map(task => `<article class="task-item ${task.status}"><div class="task-head"><h3>${task.name}</h3>${task.status === "failed" ? `<button class="retry-button" data-retry="${task.id}">重试</button>` : `<span class="task-status ${task.status === "active" && !queuePaused ? "active" : ""}">${taskStatus(task)}</span>`}</div><div class="task-sub"><span>${formatSize(task.size)}</span><span>${task.status === "active" && !queuePaused ? `${task.speed.toFixed(1)} MB/s` : `${Math.round(task.progress)}%`}</span></div><div class="task-progress"><span style="width:${task.progress}%"></span></div></article>`).join("") : '<div class="empty-state"><svg class="icon"><use href="#i-queue"/></svg><p>没有传输任务<br>返回图库选择照片开始下载</p></div>';
      $("#pause-all span").textContent = queuePaused ? "继续全部" : "暂停全部";
      $("#pause-all").disabled = !active.length;
      $("#cancel-all").disabled = !tasks.length;
      updateQueueCount();
    }

    function updateQueue() {
      let changed = false;
      tasks.forEach(task => {
        if (task.status !== "active" || queuePaused) return;
        queueTouched = true;
        changed = true;
        if (!task.baseSpeed) task.baseSpeed = task.speed;
        const jitter = 1 + (Math.random() * 2 - 1) * .08;
        task.speed = task.baseSpeed * jitter;
        task.progress = Math.min(100, task.progress + .45 + Math.random() * .85);
        if (task.progress >= 100) {
          task.status = "done";
          task.speed = 0;
          const waiting = tasks.find(item => item.status === "waiting");
          if (waiting) { waiting.status = "active"; waiting.speed = 2.6 + Math.random() * .5; }
        }
      });
      if (changed && currentScreen === "queue") renderQueue();
      if (changed) updateQueueCount();
    }
    setInterval(updateQueue, 700);

    $("#queue-list").addEventListener("click", event => {
      const retry = event.target.closest("[data-retry]");
      if (!retry) return;
      const task = tasks.find(item => item.id === Number(retry.dataset.retry));
      task.status = tasks.filter(item => item.status === "active").length < 3 ? "active" : "waiting";
      task.speed = task.status === "active" ? 2.7 : 0;
      queuePaused = false;
      queueTouched = true;
      renderQueue();
      showToast(`${task.name} 已重新加入队列`);
    });
    $("#pause-all").addEventListener("click", () => {
      queuePaused = !queuePaused;
      queueTouched = true;
      renderQueue();
      showToast(queuePaused ? "已暂停全部传输" : "传输已继续");
    });
    $("#cancel-all").addEventListener("click", () => {
      tasks = [];
      queuePaused = false;
      queueTouched = true;
      renderQueue();
      showToast("已清空传输队列");
    });
    $("#download-selected").addEventListener("click", () => {
      if (!selectedPhotos.size) return;
      const chosen = currentPhotos().filter(photo => selectedPhotos.has(photo.id));
      const activeCount = tasks.filter(task => task.status === "active").length;
      const newTasks = chosen.map((photo, index) => ({
        id: nextTaskId++, name: photo.name, size: photo.size, progress: 0,
        status: index + activeCount < 3 ? "active" : "waiting", speed: index + activeCount < 3 ? 2.5 + Math.random() : 0
      }));
      tasks = [...newTasks, ...tasks];
      selectedPhotos.clear();
      selectionMode = false;
      galleryFilter = "all";
      queuePaused = false;
      queueTouched = true;
      navigate("queue");
      showToast(`已加入 ${newTasks.length} 项，后台继续传输`);
    });

    /* ========== 界面 5：滤镜预览与 201–209 槽位写入 ========== */
    const landscapeSource = "data:image/jpeg;base64,";
    const recipes = [
      { name: "暖银盐 02", author: "Takashi Mori", filter: "sepia(.18) saturate(.78) contrast(1.08) brightness(.96)", written: true, slot: 201, params: "QUICK SHARP −1 · CONTRAST +2 · SATURATION −1" },
      { name: "静夜 Pro", author: "Lin Zhao", filter: "saturate(.58) contrast(1.16) brightness(.78) hue-rotate(8deg)", written: true, slot: 202, params: "SHARPENING +1 · CONTRAST +3 · HIGHLIGHT −2" },
      { name: "Soft Amber", author: "Mika Studio", filter: "sepia(.32) saturate(.72) contrast(.94) brightness(1.05)", written: false, slot: null, params: "CLARITY −2 · CONTRAST −1 · SATURATION −1" },
      { name: "Forest Cine", author: "North Field", filter: "saturate(.68) hue-rotate(-13deg) contrast(1.12) brightness(.9)", written: false, slot: null, params: "HUE −2 · CONTRAST +2 · SHADOW −1" },
      { name: "Mono 400", author: "Atelier N", filter: "grayscale(1) contrast(1.22) brightness(.94)", written: false, slot: null, params: "MONOCHROME · GRAIN MEDIUM · CONTRAST +2" },
      { name: "Daylight 5600", author: "Nikon Recipe", filter: "saturate(.9) contrast(1.03) brightness(1.03)", written: false, slot: null, params: "WB 5600K · CONTRAST 0 · SATURATION 0" }
    ];
    let selectedRecipe = 0;
    let previewTimer;
    let showingOriginal = false;
    let selectedSlot = 204;
    let writing = false;

    function renderRecipe(animate = false) {
      const recipe = recipes[selectedRecipe];
      const image = $("#recipe-preview-image");
      image.style.filter = recipe.filter;
      if (animate) {
        image.classList.remove("filter-changing");
        void image.offsetWidth;
        image.classList.add("filter-changing");
      }
      $("#recipe-name").textContent = recipe.name;
      $("#recipe-author").textContent = `${recipe.author} · Imaging Recipe`;
      $("#recipe-params").textContent = recipe.params;
      $("#console-recipe-name").textContent = recipe.name;
      $("#recipe-position").textContent = `${String(selectedRecipe + 1).padStart(2, "0")} / ${String(recipes.length).padStart(2, "0")}`;
      const state = $("#written-state");
      state.classList.toggle("written", recipe.written);
      $("span:last-child", state).textContent = recipe.written ? `已写入相机${recipe.slot ? ` · ${recipe.slot}` : ""}` : "未写入相机";
      $("#recipe-carousel").innerHTML = recipes.map((item, index) => `<button class="recipe-card ${index === selectedRecipe ? "selected" : ""} ${item.written ? "written" : ""}" data-recipe="${index}"><img src="${landscapeSource}" alt="${item.name}" style="filter:${item.filter}"><span class="card-dot"></span><strong>${item.name}</strong></button>`).join("");
    }

    $("#recipe-carousel").addEventListener("click", event => {
      const card = event.target.closest("[data-recipe]");
      if (!card) return;
      selectedRecipe = Number(card.dataset.recipe);
      renderRecipe(true);
    });

    function restoreRecipePreview() {
      clearTimeout(previewTimer);
      if (showingOriginal) {
        showingOriginal = false;
        $("#recipe-preview-image").style.filter = recipes[selectedRecipe].filter;
        $("#recipe-preview").classList.remove("comparing");
        $("#compare-label").textContent = "长按查看原图";
      }
    }
    $("#recipe-preview").addEventListener("pointerdown", () => {
      clearTimeout(previewTimer);
      previewTimer = setTimeout(() => {
        showingOriginal = true;
        $("#recipe-preview-image").style.filter = "none";
        $("#recipe-preview").classList.add("comparing");
        $("#compare-label").textContent = "原图 · 松手恢复";
      }, 260);
    });
    ["pointerup", "pointercancel", "pointerleave"].forEach(type => $("#recipe-preview").addEventListener(type, restoreRecipePreview));
    $("#recipe-preview").addEventListener("contextmenu", event => event.preventDefault());

    $("#phone-preview").addEventListener("click", () => {
      const recipe = recipes[selectedRecipe];
      $("#phone-preview-name").textContent = recipe.name;
      $("#phone-preview-image").style.filter = recipe.filter;
      $("#phone-preview-overlay").classList.add("visible");
    });
    ["#close-phone-preview", "#finish-phone-preview"].forEach(selector => $(selector).addEventListener("click", () => $("#phone-preview-overlay").classList.remove("visible")));

    function renderSlots() {
      const occupied = new Map(recipes.filter(recipe => recipe.written && recipe.slot).map(recipe => [recipe.slot, recipe.name]));
      $("#slot-grid").innerHTML = Array.from({ length: 9 }, (_, index) => {
        const slot = 201 + index;
        return `<button class="slot-cell ${slot === selectedSlot ? "selected" : ""}" data-slot="${slot}" ${writing ? "disabled" : ""}><span class="slot-number">${slot}</span><span class="slot-name">${occupied.get(slot) || "空槽位"}</span></button>`;
      }).join("");
      $("#slot-recipe-name").textContent = recipes[selectedRecipe].name;
      $("#confirm-write").textContent = `写入 ${selectedSlot}`;
      $("#confirm-write").disabled = writing;
    }

    function closeSlotPanel() {
      if (writing) return;
      $("#slot-panel").classList.remove("visible");
      $("#write-recipe").textContent = "写入相机";
    }

    $("#write-recipe").addEventListener("click", () => {
      const panel = $("#slot-panel");
      if (panel.classList.contains("visible")) {
        closeSlotPanel();
        return;
      }
      writing = false;
      selectedSlot = recipes[selectedRecipe].slot || 204;
      $("#write-progress-copy").textContent = "选择一个槽位开始写入";
      panel.classList.add("visible");
      $("#write-recipe").textContent = "收起槽位";
      renderSlots();
    });
    $("#close-slots").addEventListener("click", closeSlotPanel);
    $("#slot-grid").addEventListener("click", event => {
      const cell = event.target.closest("[data-slot]");
      if (!cell || writing) return;
      selectedSlot = Number(cell.dataset.slot);
      renderSlots();
    });
    $("#confirm-write").addEventListener("click", () => {
      if (writing) return;
      writing = true;
      renderSlots();
      const cell = $(`[data-slot="${selectedSlot}"]`);
      cell.classList.add("writing");
      $("#confirm-write").textContent = "正在写入";
      $("#write-progress-copy").textContent = "01 / 03 · 读取当前槽位与备份信息";
      setTimeout(() => { if (writing) $("#write-progress-copy").textContent = "02 / 03 · 写入 Picture Control 数据"; }, 520);
      setTimeout(() => { if (writing) $("#write-progress-copy").textContent = "03 / 03 · 读回校验"; }, 1060);
      setTimeout(() => {
        if (!writing) return;
        recipes.forEach(recipe => { if (recipe.slot === selectedSlot) { recipe.slot = null; recipe.written = false; } });
        const recipe = recipes[selectedRecipe];
        recipe.written = true;
        recipe.slot = selectedSlot;
        cell.classList.remove("writing");
        cell.classList.add("complete");
        $(".slot-name", cell).textContent = recipe.name;
        $("#write-progress-copy").textContent = `写入完成 · 槽位 ${selectedSlot} 已校验`;
        $("#confirm-write").textContent = "完成";
        $("#confirm-write").disabled = true;
        writing = false;
        renderRecipe();
        showToast(`${recipe.name} 已写入槽位 ${selectedSlot}`);
      }, 1580);
    });
    $("#read-camera").addEventListener("click", () => {
      const button = $("#read-camera");
      button.disabled = true;
      button.textContent = "读取中…";
      setTimeout(() => {
        recipes[2].written = true;
        recipes[2].slot = 203;
        renderRecipe();
        button.disabled = false;
        button.textContent = "从相机读取";
        showToast("已从相机读取 3 个滤镜 · 槽位 201–203");
      }, 900);
    });

    /* ========== 界面 6：年度作品统计与自动分组 ========== */
    const portfolioData = {
      2024: { count: "9,863", body: "Z f · 5,734 张", lens: "NIKKOR Z 40mm f/2 · 3,846 张", focal: "40mm（39%）", bars: [8, 14, 25, 39, 8, 4, 2] },
      2025: { count: "19,204", body: "Z 6III · 12,762 张", lens: "NIKKOR Z 24-70mm f/2.8 S · 8,309 张", focal: "50mm（29%）", bars: [5, 18, 24, 29, 14, 7, 3] },
      2026: { count: "12,847", body: "Z 6III · 8,421 张", lens: "NIKKOR Z 24-70mm f/2.8 S · 5,102 张", focal: "35mm（31%）", bars: [6, 17, 31, 22, 13, 7, 4] }
    };
    const focalLabels = ["14", "24", "35", "50", "85", "135", "200+"];
    let activeYear = 2026;
    const groups = [
      { date: "10月12日", place: "外滩", count: 47, duration: "2 小时 18 分" },
      { date: "09月28日", place: "莫干山", count: 126, duration: "4 小时 06 分" },
      { date: "08月03日", place: "阿那亚", count: 83, duration: "1 小时 52 分" }
    ];

    function renderPortfolio() {
      const data = portfolioData[activeYear];
      $("#annual-year").textContent = activeYear;
      $("#annual-count").textContent = data.count;
      $("#stat-body").textContent = data.body;
      $("#stat-lens").textContent = data.lens;
      $("#stat-focal").textContent = data.focal;
      $("#focal-bars").innerHTML = data.bars.map((value, index) => `<div class="bar-row"><span>${focalLabels[index]}</span><div class="bar-track"><span class="bar-fill" style="width:${value / 40 * 100}%"></span></div><span>${value}%</span></div>`).join("");
      $("#group-list").innerHTML = groups.map((group, index) => `<button class="group-card" data-group="${index}"><img src="data:image/jpeg;base64," alt="${group.place}" style="filter:${photoFilters[index]};object-position:${40 + index * 12}% center"><span class="group-copy"><strong>${group.date} · ${group.place}</strong><p>${group.count} 张 · ${group.duration}</p></span><svg class="icon"><use href="#i-chevron"/></svg></button>`).join("");
    }

    $$("[data-year]").forEach(button => button.addEventListener("click", () => {
      activeYear = Number(button.dataset.year);
      $$("[data-year]").forEach(item => item.classList.toggle("active", item === button));
      renderPortfolio();
    }));
    $("#group-list").addEventListener("click", event => {
      const button = event.target.closest("[data-group]");
      if (!button) return;
      const group = groups[Number(button.dataset.group)];
      $("#collection-title").textContent = `${group.date} · ${group.place}`;
      $("#collection-meta").textContent = `${group.count} 张 · ${group.duration} · Z 6III`;
      $("#collection-grid").innerHTML = cameraPhotos.map(photo => `<div class="photo-cell"><img src="data:image/jpeg;base64," alt="${group.place}作品" style="filter:${photo.filter};object-position:${photo.position}">${photo.type === "RAW" ? '<span class="raw-badge">RAW</span>' : ""}</div>`).join("");
      $("#collection-overlay").classList.add("visible");
    });
    $("#close-collection").addEventListener("click", () => $("#collection-overlay").classList.remove("visible"));

    /* ========== 初始状态 ========== */
    renderParameters();
    renderGallery();
    renderQueue();
    renderRecipe();
    renderPortfolio();
  